import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong(), extra = nextLong();
        long total = extra, largest = 0;
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            total += v;
            largest = Math.max(largest, v);
        }
        // Neither the old maximum nor the ceiling of the average can be beaten, and both are reachable.
        System.out.println(Math.max(largest, (total + n - 1) / n));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, extra := nextInt(), nextInt()
	total := extra
	var largest int64
	for i := int64(0); i < n; i++ {
		v := nextInt()
		total += v
		largest = max(largest, v)
	}
	// Neither the old maximum nor the ceiling of the average can be beaten, and both are reachable.
	fmt.Println(max(largest, (total+n-1)/n))
}
